&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; color: rgb(204, 9, 47);&quot;&gt;&lt;strong&gt;Apply today to join our talent network!&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
