&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You have implemented&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;monitoring and observability solutions&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;with a security lens (New Relic, Prometheus, Grafana, ELK).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You are fluent in at least one&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;scripting/programming language&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;(Python, Go, Bash, etc.) for automation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;8&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You are experienced in&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IAM,&amp;nbsp;secrets&amp;nbsp;management, and zero-trust principles&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;9&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You are a natural mentor, able to upskill and guide other engineers.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nice to have qualifications &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong communication and presentation skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Accountability, collaboration, and time-management skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong desire to learn more about business every day&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The benefits &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a &lt;strong&gt;Full time&lt;/strong&gt; position based in &lt;strong&gt;Buenos Aires&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. If your skills and experience align with the role, we’ll reach out for next steps.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt; &lt;span data-teams=&quot;true&quot;&gt;Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud: Only engage with official Valtech email addresses.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/p&gt;

startx-valtech:greenhouse:4880632101.descriptionHtml:
&lt;h1&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Senior SFCC Multicloud Backend Engineer (all genders)&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW246265904 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;Why Valtech?&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;We’re&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;the&lt;/span&gt; &lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;experience&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; innovation company &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;- &lt;/span&gt;&lt;span class=&quot;NormalTextRun CommentStart SCXW246265904 BCX0&quot;&gt;a&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; trusted partner&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; to the world’s most recognized brands. To our people we offer &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;growth opportunities, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;a &lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW246265904 BCX0&quot;&gt;values&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;-driven culture, &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;international &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt;careers&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW246265904 BCX0&quot;&gt; and the chance to shape the future of experience.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP CommentStart SCXW246265904 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The opportunity&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, you’ll find an environment designed for continuous learning, meaningful impact, and professional growth. Whether you&#39;re pioneering new digital solutions, challenging conventional thinking or building the next generation of customer experiences, your work will help transform industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are proud of:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/work/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;The work we do and the innovation we drive&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/career/our-values/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our values of share, care &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;nd dare&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/valtech-as-workplace/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;A workplace culture that fosters creativity, diversity and autonomy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.valtech.com/about/offices/?utm_source=greenhouse&amp;amp;utm_medium=website&amp;amp;utm_campaign=gl_ta_talent-acquisition_aw_ba_job_description_template&amp;amp;utm_term=website-applicants&amp;amp;utm_content=job-applicants_week192025&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Our borderless, global framework, &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;which enables &lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;seamless collaboration&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;The role&amp;nbsp;&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;As a &lt;strong&gt;Senior SFCC Multicloud Backend Engineer (all genders)&lt;/strong&gt;, you are passionate about experience innovation and eager to push the boundaries of what’s possible. You bring&lt;strong&gt; +8 years &lt;/strong&gt;of experience, a growth mindset and a drive to make a lasting impact.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You will thrive in this role if you are:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A curious problem solver who challenges the status quo&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A collaborator who values teamwork and knowledge-sharing&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Excited by the intersection of technology, creativity and data&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experienced in Agile methodologies and consulting (a plus)&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Role responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner with key Technical Stakeholders to identify and document requirements for the purposes of deploying new (global and regional) systems&lt;/li&gt;
&lt;li&gt;Manage technical stakeholder approval for all technical designs and optimizations&lt;/li&gt;
&lt;li&gt;Develop and support the creation of technical related materials such as solution documents, technical and architectural requirements, performance documents&lt;/li&gt;
&lt;li&gt;Coordinate and work with technical team on technical design, delivery and support&lt;/li&gt;
&lt;li&gt;Organize, equip and facilitate application technical test plans and technical test cases including performance tests, load tests, etc.)&lt;/li&gt;
&lt;li&gt;Provide ongoing application system maintenance and problem resolution with internal/external supporting teams&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Must have qualifications&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;To be considered for this role, you must meet the following essential qualifications:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;University degree in IT, Business Information System or equivalent&lt;/li&gt;
&lt;li&gt;+ 8 years of experience in IT, with at least + 5 years experience in e-commerce architecture (luxury preferred)&lt;/li&gt;
&lt;li&gt;Experience related to e-commerce solutions implementations in an international context&lt;/li&gt;
&lt;li&gt;Multi-cultural projects experienced&lt;/li&gt;
&lt;li&gt;Technical lead and time management abilities&lt;/li&gt;
&lt;li&gt;You process an in-depth working knowledge of Salesforce in (one or more) of the followings&amp;nbsp;:&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Commerce Cloud &amp;amp; OMS&lt;/li&gt;
&lt;li&gt;Core&lt;/li&gt;
&lt;li&gt;Marketing Cloud&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;You are technical-oriented: strong technical sense and technical operational experience&lt;/li&gt;
&lt;li&gt;You have a good ability to liaise between the business and technical communities bridging the gap and driving discussions toward a collaborative solution&lt;/li&gt;
&lt;li&gt;You have strong organization, planning, communication, project management and presentation skills&lt;/li&gt;
&lt;li&gt;You know how to work under pressure and to meet tight deadlines&lt;/li&gt;
&lt;li&gt;You’re fluent in French and English, both written and oral&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Nice to have qualifications&lt;/strong&gt; &amp;nbsp;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience with agility using SAFe&lt;/li&gt;
&lt;li&gt;A willingness to constantly seek new ways to learn, grow, and adapt when needed&lt;/li&gt;
&lt;li&gt;A team-oriented mindset&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW105898609 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW105898609 BCX0&quot;&gt;If you do not meet all the listed qualifications or have gaps in your experience, we still encourage you to apply. At Valtech, we recognize that talent comes in many forms, and we value diverse perspectives and a willingness to learn.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW105898609 BCX0&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Commitment to reaching all kinds of people&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We design experiences that work for all kinds of people - and that starts with our own teams. At Valtech, we’re intentional about building an inclusive culture where everyone feels supported to grow, thrive and achieve their goals. No matter your background, you belong here. &lt;/span&gt;&lt;a href=&quot;https://www.valtech.com/about/diversity-inclusion/&quot; target=&quot;_blank&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Explore our Diversity &amp;amp; Inclusion site&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to see how we’re creating a more equitable Valtech for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The benefits &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a &lt;strong&gt;permanent&lt;/strong&gt; position based in &lt;strong&gt;Paris / France&lt;/strong&gt;.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Beyond a competitive compensation package, we offer:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Flexibility, with remote and hybrid work options (country-dependent)&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Career advancement, with international mobility and professional development programs&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Learning and development, with access to cutting-edge tools, training and industry experts&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our benefits are tailored to each location. Your Talent Partner will provide full details during the hiring process.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your application process&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Once you apply, our Talent Acquisition team will review your application. Your CV should cover key information on relevant experiences and expertise. We do not require information such as age, gender, marital status, or a headshot in your application. We review all candidates based on skills, experience, and potential.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;⚠️ Beware of recruitment fraud!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are committed to inclusion and accessibility. If you need reasonable accommodations during the interview process, please either indicate it in your application or let your Talent Partner know.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About Valtech&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Valtech is the experience innovation company that exists to unlock a better way to experience the world. By blending crafts, categories, and cultures, we help brands unlock new value in an increasingly digital world.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At the intersection of data, AI, creativity, and technology, we drive transformation for leading organizations, including L’Oréal, Mars, Audi, P&amp;amp;G, Volkswagen Dolby, and more.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Valtech, we don’t just talk about transformation. We make it happen. Our people are the heart of our success, and we foster a workplace where everyone has the support to thrive, grow and innovate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you ready to create what’s next? Join us.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;em&gt;As per the AGG (General Equal Treatment Act) in Germany and equivalent in France, jobs must be advertised in a gender-neutral manner. We use the statement (all genders) to make it clear that this position is open to all genders in these countries, even if the job title itself can be translated or interpreted as &quot;masculine&quot; in the French or German language.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;

techaviv-taboola:greenhouse:7546323.descriptionHtml:
&lt;p&gt;&lt;strong&gt;Realize your potential by joining the leading performance-driven advertising company!&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Taboola, the world’s largest content recommendation platform, is hiring a&lt;strong&gt; Senior Performance Account Manager&lt;/strong&gt;&amp;nbsp;for our TLV Office. In this role, you will be directly responsible for managing a book of business of tier-1 clients, identifying and executing upsell &amp;amp; optimization opportunities at scale.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You will excel in this role if you enjoy working in a highly technological &amp;amp; analytical environment, and love developing rock-solid relationships with international clients.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;strong&gt;To thrive in this role, you&#39;ll need:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;B.A / BSc degree&lt;/li&gt;
&lt;li&gt;5+ years of professional client facing experience in a B2B client-facing role&amp;nbsp;in the Programmatic / Performance Marketing space - a must&lt;/li&gt;
&lt;li&gt;Ability to provide world-class client service while keeping a focus on growing revenues&lt;/li&gt;
&lt;li&gt;Strong analytical skills - proficient in working with Excel advanced functions. Familiarity with BI platforms such as Tableau / QlikSense / Looker - an advantage&lt;/li&gt;
&lt;li&gt;Love for data-driven decision making - ability to monitor, A/B test and identify trends in data to generate action items and insights&lt;/li&gt;
&lt;li&gt;Excited about complex analytical challenges and enjoy solving them&lt;/li&gt;
&lt;li&gt;Fluency in English&lt;/li&gt;
&lt;li&gt;You are highly motivated, super proactive and dedicated person&lt;/li&gt;
&lt;li&gt;You are a natural collaborator, able to work with multiple teams to reach a common goal&lt;/li&gt;
&lt;li&gt;You are a quick learner with great attention to details and multi-tasking capabilities&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus points if you have:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience working with programmatic platforms (SSPs &amp;amp; DSPs) on different types of integrations, preferably OpenRTB&lt;/li&gt;
&lt;li&gt;A love for the challenge of upselling and relationship building with large, international B2B organizations&lt;/li&gt;
&lt;li&gt;Familiarity with different AI tools and the ambition to adopt LLM based functions to improve productivity&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;How you’ll make an impact:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Manage a book of business of programmatic partners - understand client strategic objectives &amp;amp; KPIs in order to be able to intelligently identify and execute opportunities, upsell effectively and grow the overall partnership&lt;/li&gt;
&lt;li&gt;Monitor, troubleshoot and optimize performance for different types of client integrations and activities&lt;/li&gt;
&lt;li&gt;Use data analytics tools (Tableau, QlikSense, Excel, etc.) on a daily basis to draw business conclusions and identify opportunities for growth&lt;/li&gt;
&lt;li&gt;Routinely meet &amp;amp; have weekly calls with your clients to share insights &amp;amp; potential initiatives, and review overall performance - backed by data&lt;/li&gt;
&lt;li&gt;Successfully build and maintain close relationships with key people in your book-of-business. Strengthen partnerships with clients and influence their business strategy &amp;amp; decision making&lt;/li&gt;
&lt;li&gt;Develop and execute long-term account plans and conduct QBR (quarterly business review) meetings with strategic clients&lt;/li&gt;
&lt;li&gt;Work very closely with Product Management- as well as other internal teams - to increase client engagement by building new features / improving products based on clients feedback, as well as troubling technical issues&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Why Taboola?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;If you ask Taboolars what they love about working here, they’ll tell you that they’ve been empowered to realize their full potential while growing and learning from and with smart and talented people. They’ll also share more about:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Adam Singolda, Taboola Founder and CEO says; “You can copy anything from another business but you can’t copy a company’s culture.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Well-being:&lt;/strong&gt; Enjoy comprehensive benefits (health, etc.), a fully stocked kitchen, and location-specific perks (gym, parking).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Flexibility: &lt;/strong&gt;We offer a hybrid work schedule with 3 days in-office with an option to come in more often if desired.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Work with some of the biggest names: &lt;/strong&gt;Our publisher partners include Yahoo, Conde Nast, Fox Sports, NBCU, ESPN, CBS, and E! Online. Our advertiser clients include Wells Fargo, Honda, Pinterest, Expedia and Honda.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Ready to realize your potential?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Taboola is an equal opportunity employer and we value diversity in all forms. We are committed to creating an inclusive environment for all employees and believe such an environment is critical for success. Employment is decided on the basis of qualifications, merit, and business need.&lt;/p&gt;
&lt;p&gt;Learn more about #TaboolaLife on&lt;a href=&quot;https://www.linkedin.com/search/results/all/?fetchDeterministicClustersOnly=true&amp;amp;heroEntityKey=urn%3Ali%3Aorganization%3A128707&amp;amp;keywords=taboola&amp;amp;origin=RICH_QUERY_SUGGESTION&amp;amp;position=2&amp;amp;searchId=dcc8bfbb-b05c-458e-a7f1-726d30e7dd80&amp;amp;sid=9(y&amp;amp;spellCorrectionEnabled=false&quot;&gt; LinkedIn&lt;/a&gt;,&lt;a href=&quot;https://www.facebook.com/taboola/&quot;&gt; Facebook&lt;/a&gt;,&lt;a href=&quot;https://www.instagram.com/taboola.israel/?hl=en&quot;&gt; Instagram&lt;/a&gt;,&lt;a href=&quot;https://docs.google.com/document/d/1BctKkw2Vj_EOjvy24kjRKq_ZxZzmZxweIqNLQgsLtcs/edit?tab=t.0&quot;&gt; X&lt;/a&gt;,&lt;a href=&quot;https://www.youtube.com/channel/UC6W0hdStO0jRVYhg4ABzjRw&quot;&gt; YouTube&lt;/a&gt;, &amp;amp; the&lt;a href=&quot;https://bit.ly/41kidx9&quot;&gt; Taboola Life Blog&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Taboola&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Taboola empowers businesses to grow through performance advertising technology that goes beyond search and social and delivers measurable outcomes at scale.&lt;/p&gt;
&lt;p&gt;Taboola works with thousands of businesses who advertise directly on Realize, Taboola’s powerful ad platform, reaching approximately 600M daily active users across some of the best publishers in the world. Publishers like NBC News, Yahoo, and OEMs such as Samsung, Xiaomi and others use Taboola’s technology to grow audience and revenue, enabling Realize to offer unique data, specialized algorithms, and unmatched scale.&lt;/p&gt;
&lt;p&gt;#LI-GG1&lt;/p&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;

techchange-one-acre-fund:greenhouse:7953.descriptionHtml:
&lt;h3&gt;About One Acre Fund&lt;/h3&gt;
&lt;p&gt;Founded in 2006, One Acre Fund equips 5.5 million smallholder farmers to make their farms more productive. Across nine countries that together are home to two-thirds of Africa&#39;s farmers, we provide high-quality farm supplies, tree seedlings, accessible credit, modern agronomic training, and a wide range of other agricultural services. On average, this model enables any farmer to increase their income and assets on supported land by more than 35 percent, while permanently improving their resilience. This is all made possible by our team of 9,000+ full-time staff, drawn from diverse backgrounds and professions.&amp;nbsp;To learn more, please see our&amp;nbsp;&lt;a href=&quot;https://oneacrefund.org/careers/why-work-here&quot; target=&quot;_blank&quot;&gt;Why Work Here&lt;/a&gt; blog post.&lt;/p&gt;
&lt;p&gt;One Acre Fund runs a pilot program in Zambia’s Central Province. Our Zambia pilot is exploring ways we can help farmers improve harvests on larger plots of land, which are common in the country. Our office in Zambia is located in Kabwe, the capital of the Central Province.&lt;/p&gt;
&lt;h3&gt;About the Role&lt;/h3&gt;
&lt;p&gt;We are seeking a Senior People Leader to own Zambia’s People function and serve as a strategic partner to the COO. You will design and execute a comprehensive People strategy with a heavy emphasis on building a culture of continuous learning and professional growth. Beyond ensuring operational excellence for a scaling program of 200+ staff, you will spearhead Learning and Development initiatives, mentor HR talent, and develop the internal pipelines necessary to sustain our rapid expansion.&lt;/p&gt;
&lt;p&gt;You will report to the Deputy Country Manager.&lt;/p&gt;
&lt;h3&gt;Responsibilities&lt;/h3&gt;
&lt;p&gt;Lead Zambia’s People strategy and function&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Serve as the senior People partner to the COO and country leadership team, helping shape and execute Zambia’s People strategy for a rapidly scaling program.&lt;/li&gt;
&lt;li&gt;Provide oversight and accountability for the Zambia People function, ensuring strong HR operations, people systems, and staff support across HQ and field teams.&lt;/li&gt;
&lt;li&gt;Identify, prioritize, and address organizational and people challenges before they become structural barriers to growth, performance, or staff experience.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Build staff capability through learning and development&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Design and implement practical learning and development strategies that improve staff capability and performance across field and HQ teams.&lt;/li&gt;
&lt;li&gt;Develop and oversee training programs including workshops, bootcamps, coaching approaches, onboarding systems, and repeatable learning tools.&lt;/li&gt;
&lt;li&gt;Partner with Field, Impact, and Global teams to strengthen learning outcomes and improve consistency and quality of execution across teams.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Strengthen people systems, culture, and staff experience&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Improve core people systems, including onboarding, career pathing, feedback loops, and staff development processes to support engagement, retention, and long-term growth.&lt;/li&gt;
&lt;li&gt;Support the development of a healthy, high-performing team culture through practical and sustainable staff experience initiatives.&lt;/li&gt;
&lt;li&gt;Use performance data, surveys, feedback, and field observations to identify organizational capability gaps and improve staff effectiveness.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Lead and develop People and Corporate Operations staff&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Mentor and develop HR and Corporate Operations staff, building stronger management capability, ownership, and execution across the team.&lt;/li&gt;
&lt;li&gt;Support performance management, prioritization, and professional development of direct reports and broader People team members.&lt;/li&gt;
&lt;li&gt;Build systems and ways of working that improve team effectiveness, accountability, and service delivery as the Zambia program continues to scale.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Career Growth and Development&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We have a strong culture of constant learning and we invest in developing our people. You’ll have weekly check-ins with your manager, access to mentorship and training programs, and regular feedback on your performance. We hold career reviews every six months, and set aside time to discuss your aspirations and career goals. You’ll have the opportunity to shape a growing organization and build a rewarding long-term career.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Qualifications&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Across all roles, these are the &lt;/span&gt;&lt;a href=&quot;https://oneacrefund.org/work-with-us/application-process/qualifications/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;general qualifications we look for&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; For this role specifically, you will have:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience managing or mentoring junior team members, with a demonstrated ability to develop others.&lt;/li&gt;
&lt;li&gt;Proven track record in designing and delivering training or capacity-building programs that improve performance.&lt;/li&gt;
&lt;li&gt;Strong facilitation skills and the ability to make complex ideas clear, practical, and usable.&lt;/li&gt;
&lt;li&gt;Experience using data, such as surveys, feedback, performance metrics, or field observations, to improve learning outcomes.&lt;/li&gt;
&lt;li&gt;Strong project and program management skills, with the ability to manage multiple priorities and deliver high-quality work on time.&lt;/li&gt;
&lt;li&gt;Strong leadership and execution skills, with a clear bias toward action and results.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Start Date&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;As soon as possible&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Job Location&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Kabwe, Zambia&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Benefits&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Health insurance, housing, and comprehensive benefits&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Eligibility&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;This role is only open to citizens or permanent residents of Zambia.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Application Deadline&lt;/h3&gt;
&lt;p&gt;26 August 2026. Please note that we hire on a rolling basis, which means that applications are reviewed and processed on a continuous basis until a hire is made.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;One Acre Fund never asks candidates to pay any money or pay for tests at any stage of the interview process. Official One Acre Fund emails will always arrive from an @&lt;a href=&quot;http://oneacrefund.org/&quot;&gt;oneacrefund.org&lt;/a&gt;&amp;nbsp;address. Please report any suspicious communication here (&lt;a href=&quot;mailto:globalhotline@oneacrefund.org&quot;&gt;globalhotline@oneacrefund.org&lt;/a&gt;),&amp;nbsp;&lt;strong&gt;but do not send applications or application materials to this email address.&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Diversity, Equity, Inclusion (DEI), and anti-racism are deeply connected to our organization’s mission and purpose. One Acre Fund aspires to build a culture where all staff feel consistently valued, represented, and connected – so that our team can thrive as professionals, and achieve exceptional impact for the farmers we serve.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are committed to equal employment opportunity regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, marital status, disability, gender, gender identity or expression. We are proud to be an equal opportunity workplace.&lt;/em&gt;&lt;/p&gt;

techchange-one-acre-fund:greenhouse:7958.descriptionHtml:
&lt;h3&gt;About One Acre Fund&lt;/h3&gt;
&lt;p&gt;Founded in 2006, One Acre Fund equips 5.5 million smallholder farmers to make their farms more productive. Across nine countries that together are home to two-thirds of Africa&#39;s farmers, we provide high-quality farm supplies, tree seedlings, accessible credit, modern agronomic training, and a wide range of other agricultural services. On average, this model enables any farmer to increase their income and assets on supported land by more than 35 percent, while permanently improving their resilience. This is all made possible by our team of 9,000+ full-time staff, drawn from diverse backgrounds and professions.&amp;nbsp;To learn more, please see our&amp;nbsp;&lt;a href=&quot;https://oneacrefund.org/careers/why-work-here&quot; target=&quot;_blank&quot;&gt;Why Work Here&lt;/a&gt; blog post.&lt;/p&gt;
&lt;h3&gt;About the Role&lt;/h3&gt;
&lt;p&gt;Our Creative Lead will work as a deputy to our Creative Director on our Global Communications team, and will manage the Global Comms team support request systems and oversee all incoming creative requests, delegating those out to team units and helping ensure the team is upkeeping our SLAs and quality. They will be a strong contributor to creative brainstorms and ideation, will support the organization’s brand management, and will review all creative content for quality, holding last line creative reviews for Tier 2 and Tier 3 content.&lt;br&gt;This position will also manage and be responsible for the professional development of a creative team of ~5 people working on graphic design and video, directly managing ~3 reports.&lt;/p&gt;
&lt;h3&gt;Responsibilities&lt;/h3&gt;
&lt;p&gt;Creative Content Quality Review &amp;amp; Brand Management&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Hold quality bar and last line reviews for Tier 2 and Tier 3 creative content running through Global Comms&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Review and give feedback to improve quality on writing, design, photography, and video&lt;/li&gt;
&lt;li&gt;Accountable for final sign off on Tier 2 and Tier 3 content before it’s published&lt;/li&gt;
&lt;li&gt;Engage in brand building and advising for new affiliates within the org’s brand families&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;Engage in brand building and advising for new affiliates within the org’s brand families&lt;/li&gt;
&lt;li&gt;Drive brand guideline expansions and evolutions to better serve our markets as needed (example, work with the Design Lead to build out youth brand guidelines)&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Run &amp;amp; Improve Comms Support Systems&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Build, maintain, and improve single Comms support request form&lt;/li&gt;
&lt;li&gt;Receive incoming requests and delegate those out to team units&lt;/li&gt;
&lt;li&gt;Ensure the team is upkeeping our SLAs and quality&lt;/li&gt;
&lt;li&gt;Continually improve our content storing and sharing systems as well as templates, with the support of the Comms team to execute improvements&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Creative Brainstorming &amp;amp; Ideation&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Contribute to campaign, brand, and design brainstorming and ideation&lt;/li&gt;
&lt;li&gt;Contribute to content planning and design content that can be cross purposed based on upcoming content plans&lt;/li&gt;
&lt;li&gt;Hold standing touch points with Internal comms, External comms, Digital and BizDev to support content planning and production&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Career Growth and Development&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We have a strong culture of constant learning and we invest in developing our people. You’ll have weekly check-ins with your manager, access to mentorship and training programs, and regular feedback on your performance. We hold career reviews every six months, and set aside time to discuss your aspirations and career goals. You’ll have the opportunity to shape a growing organization and build a rewarding long-term career.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Qualifications&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Across all roles, these are the &lt;/span&gt;&lt;a href=&quot;https://oneacrefund.org/work-with-us/application-process/qualifications/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;general qualifications we look for&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; For this role specifically, you will have:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Keen attention to detail for reviewing and upholding a quality bar&lt;/li&gt;
&lt;li&gt;Strong project management and organization skills&lt;/li&gt;
&lt;li&gt;Strong project management and organization skills&lt;/li&gt;
&lt;li&gt;Strong people management skills and culture setting skills&lt;/li&gt;
&lt;li&gt;Proficient in Google Suite&lt;/li&gt;
&lt;li&gt;Expertise with Adobe Creative Suite&lt;/li&gt;
&lt;li&gt;Technical expertise in one or multiple creative fields, i.e. graphic design, video, photography, or writing knowledge&lt;/li&gt;
&lt;li&gt;Strong understanding of One Acre Fund’s brand, what makes it unique, and how to translate that across mediums in content&lt;/li&gt;
&lt;li&gt;Strong knowledge of one or more of the markets where One Acre Fund operates&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Start Date&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;As soon as possible&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Job Location&lt;/h3&gt;
&lt;p&gt;Countries of operation&lt;/p&gt;
&lt;h3&gt;Benefits&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Health insurance, housing, and comprehensive benefits&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Eligibility&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;This role is only open to citizens or permanent residents of Kenya, Rwanda, Burundi, Uganda, Tanzania, Malawi, Zambia, Nigeria, Ethiopia and the Democratic Republic of Congo.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;Application Deadline&lt;/h3&gt;
&lt;p&gt;26 August 2026. Please note that we hire on a rolling basis which means that applications are reviewed and processed on a continuous basis until a hire is made.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;One Acre Fund never asks candidates to pay any money or pay for tests at any stage of the interview process. Official One Acre Fund emails will always arrive from an @&lt;a href=&quot;http://oneacrefund.org/&quot;&gt;oneacrefund.org&lt;/a&gt;&amp;nbsp;address. Please report any suspicious communication here (&lt;a href=&quot;mailto:globalhotline@oneacrefund.org&quot;&gt;globalhotline@oneacrefund.org&lt;/a&gt;),&amp;nbsp;&lt;strong&gt;but do not send applications or application materials to this email address.&lt;/strong&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Diversity, Equity, Inclusion (DEI), and anti-racism are deeply connected to our organization’s mission and purpose. One Acre Fund aspires to build a culture where all staff feel consistently valued, represented, and connected – so that our team can thrive as professionals, and achieve exceptional impact for the farmers we serve.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are committed to equal employment opportunity regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, marital status, disability, gender, gender identity or expression. We are proud to be an equal opportunity workplace.&lt;/em&gt;&lt;/p&gt;

